export type YoutubeContentCardProps = Record<string, any>;

const YoutubeContentCard: React.FC<YoutubeContentCardProps> = ({
  backgroundColor = "#FFFFFF",
  transparentBackground = false,
  durationInSeconds = 8,
  thumbnailImage = "https://malloy.blob.core.windows.net/web/testing/maxresdefault (3).jpg",
  profileImage = "https://malloy.blob.core.windows.net/web/testing/channels4_profile.jpg",
  titleText = "Marty Supreme | Official Teaser HD | A24",
  channelName = "A24",
  subscriberCount = "13.3K subscribers",
  primaryTextColor = "#ffffff",
  secondaryTextColor = "#aaaaaa",
  accentColor = "#ffffff",
  cardBackgroundColor = "#121212", // Dark card background like reference
}) => {
  useFontLoader(["Roboto"]);

  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  // --- Layout Calculation ---
  // Determine target size for the card
  const maxContentWidth = 1200;
  const safeMargin = Math.min(width, height) * 0.05;
  const maxVerticalSpaceForThumb = height * 0.55; 
  const maxThumbWidth = maxVerticalSpaceForThumb * (16 / 9);
  
  const targetContentWidth = Math.min(
    width - (safeMargin * 2),
    maxThumbWidth,
    maxContentWidth
  );

  const baseFontSize = targetContentWidth * 0.022; 
  const gapSize = targetContentWidth * 0.015;
  const iconSize = baseFontSize * 1.2;

  // --- Animation Configuration ---
  const easeInOutSpring = {
    damping: 20,
    stiffness: 70,
    mass: 1.5, // Heavier mass for premium feel
  };

  const createSpring = (delay: number) =>
    spring({
      frame: frame - delay,
      fps,
      config: easeInOutSpring,
    });

  // 1. Morph Animation (Full Screen Image -> Card)
  // Starts after a brief moment to establish the "full frame" look
  const morphStartDelay = 15;
  const morphSpring = createSpring(morphStartDelay);

  // Width: Interpolate from Viewport Width (Full) down to Target Content Width
  const currentWidth = interpolate(morphSpring, [0, 1], [width, targetContentWidth]);
  
  // Radius: Square (0) -> Rounded (32px)
  const currentRadius = interpolate(morphSpring, [0, 1], [0, 32]);
  
  // Shadow: None -> Drop Shadow
  const shadowOpacity = interpolate(morphSpring, [0, 1], [0, 0.4]);
  
  // 2. Content Reveal Animation (Text below image)
  // Starts slightly after morph begins
  const contentRevealSpring = createSpring(morphStartDelay + 10);
  const contentOpacity = interpolate(contentRevealSpring, [0, 1], [0, 1]);
  const contentY = interpolate(contentRevealSpring, [0, 1], [40, 0]);

  // 3. Action Bar Animation (Social icons)
  // Appears last with soft ease
  const actionsSpring = createSpring(morphStartDelay + 25);
  const actionsOpacity = interpolate(actionsSpring, [0, 1], [0, 1]);
  const actionsY = interpolate(actionsSpring, [0, 1], [20, 0]);

  // Background handling
  const finalBgColor = transparentBackground ? "transparent" : backgroundColor;

  return (
    <AbsoluteFill
      style={{
        backgroundColor: finalBgColor,
        fontFamily: "Roboto, sans-serif",
        display: "flex",
        justifyContent: "center",
        alignItems: "center",
        // No padding here to allow full-bleed start
      }}
    >
      {/* 
        The Morphing Card Container
        - Starts as full width/height (effectively)
        - Morphs to rounded card 
      */}
      <div
        style={{
          width: currentWidth,
          backgroundColor: cardBackgroundColor, // The "Card" background (dark)
          borderRadius: currentRadius,
          overflow: "hidden", // Clips the image to corners
          display: "flex",
          flexDirection: "column",
          boxShadow: `0 20px 50px rgba(0,0,0,${shadowOpacity})`,
          position: "relative",
          // When full width, this ensures it covers 16:9 fully centered
          transformOrigin: "center center", 
        }}
      >
        {/* --- Thumbnail Image (Top of Card) --- */}
        <div
          style={{
            width: "100%",
            aspectRatio: "16/9",
            position: "relative",
            zIndex: 1,
          }}
        >
           <Img
            src={thumbnailImage}
            style={{
              width: "100%",
              height: "100%",
              objectFit: "cover",
              display: "block", // Remove inline-block spacing
            }}
          />
        </div>

        {/* --- Content Section (Below Image) --- */}
        {/* Only visible as the card forms */}
        <div
          style={{
            padding: `${gapSize * 1.5}px ${gapSize * 1.5}px`,
            display: "flex",
            flexDirection: "column",
            gap: gapSize,
            opacity: contentOpacity,
            transform: `translateY(${contentY}px)`,
          }}
        >
          {/* Title */}
          <div
            style={{
              fontSize: baseFontSize * 1.4,
              fontWeight: 700,
              color: primaryTextColor,
              lineHeight: 1.2,
            }}
          >
            {titleText}
          </div>

          {/* Metadata Row */}
          <div
            style={{
              display: "flex",
              flexDirection: "row",
              justifyContent: "space-between",
              alignItems: "center",
              flexWrap: "wrap",
              gap: gapSize,
              marginTop: gapSize * 0.5,
            }}
          >
            {/* Left: Profile & Info */}
            <div style={{ display: "flex", alignItems: "center", gap: gapSize }}>
              <Img
                src={profileImage}
                style={{
                  width: baseFontSize * 2.5,
                  height: baseFontSize * 2.5,
                  borderRadius: "50%",
                  objectFit: "cover",
                }}
              />
              <div style={{ display: "flex", flexDirection: "column" }}>
                <span
                  style={{
                    fontSize: baseFontSize,
                    fontWeight: 700,
                    color: primaryTextColor,
                  }}
                >
                  {channelName}
                </span>
                <span
                  style={{
                    fontSize: baseFontSize * 0.75,
                    color: secondaryTextColor,
                  }}
                >
                  {subscriberCount}
                </span>
              </div>
              
              <div
                style={{
                  backgroundColor: "#2e2e2e",
                  color: primaryTextColor,
                  padding: `${gapSize * 0.4}px ${gapSize * 1}px`,
                  borderRadius: 20,
                  fontSize: baseFontSize * 0.85,
                  fontWeight: 600,
                  marginLeft: gapSize * 0.5,
                  cursor: "pointer",
                }}
              >
                Subscribe
              </div>
            </div>

            {/* Right: Actions (Delayed Animation) */}
            <div
              style={{
                display: "flex",
                alignItems: "center",
                gap: gapSize * 0.5,
                backgroundColor: "#1e1e1e", // Slightly lighter than card bg for contrast
                padding: `${gapSize * 0.4}px ${gapSize * 0.8}px`,
                borderRadius: 50,
                border: "1px solid #333",
                opacity: actionsOpacity,
                transform: `translateY(${actionsY}px)`,
              }}
            >
              {/* Share */}
              <div style={actionButtonStyle(baseFontSize)}>
                <div style={{ width: iconSize, height: iconSize }}>
                  <ShareIcon />
                </div>
                <span style={{ marginLeft: gapSize * 0.4 }}>Share</span>
              </div>
              
              <div style={{ width: 1, height: baseFontSize * 1.2, backgroundColor: "#444" }} />

              {/* Download */}
              <div style={actionButtonStyle(baseFontSize)}>
                <div style={{ width: iconSize, height: iconSize }}>
                  <DownloadIcon />
                </div>
                <span style={{ marginLeft: gapSize * 0.4 }}>Download</span>
              </div>

              <div style={{ width: 1, height: baseFontSize * 1.2, backgroundColor: "#444" }} />

              {/* Save */}
              <div style={actionButtonStyle(baseFontSize)}>
                <div style={{ width: iconSize, height: iconSize }}>
                  <SaveIcon />
                </div>
                <span style={{ marginLeft: gapSize * 0.4 }}>Save</span>
              </div>

              <div style={{ width: 1, height: baseFontSize * 1.2, backgroundColor: "#444" }} />

              {/* Menu */}
              <div style={{ ...actionButtonStyle(baseFontSize), paddingLeft: gapSize * 0.2 }}>
                <div style={{ width: iconSize, height: iconSize }}>
                  <MenuIcon />
                </div>
              </div>
            </div>
          </div>
        </div>
      </div>
    </AbsoluteFill>
  );
};

const actionButtonStyle = (fontSize: number): React.CSSProperties => ({
  display: "flex",
  alignItems: "center",
  color: "#e0e0e0",
  fontSize: fontSize * 0.75,
  fontWeight: 600,
  cursor: "pointer",
  padding: `0 ${fontSize * 0.3}px`,
});

export default YoutubeContentCard;